use vstd::prelude::*;

verus! {
    /// Given
    ///   * `indices`: a non‐empty vector of row‐indices,
    ///   * `choices`: a non‐empty matrix (vector of rows),
    /// where
    ///   1. every row of `choices` has the same length as `indices`,
    ///   2. each `indices[i]` is a valid row in `choices`,
    /// this function returns a vector `res` of the same length as `indices`,
    /// such that
    ///   res[i] == choices[ indices[i] as usize ][ i ].
    fn choose(indices: Vec<u8>, choices: Vec<Vec<f64>>) -> Vec<f64>
        requires
            // There is at least one row.
            choices.len() > 0,
            // Every row has the same length as indices.
            forall |row: usize|
                row < choices.len() ==>
                choices[row].len() == indices.len(),
            // Every index is a valid row selector.
            forall |i: usize|
                i < indices.len() ==>
                (indices[i] as usize) < choices.len(),
        ensures
            |res: &Vec<f64>|
                // The result has the same length as indices
                res.len() == indices.len() &&
                // And for each position i, we chose the correct element.
                forall |i: usize|
                    i < indices.len() ==>
                    res[i] == choices[(indices[i] as usize)][i],
    {
        let mut res: Vec<f64> = Vec::new();
        let mut i: usize = 0;
        // We'll build up `res` one element at a time.
        while i < indices.len()
            invariant
                // `i` walks from 0 to indices.len()
                i <= indices.len(),
                // We've already pushed exactly `i` elements
                res.len() == i,
                // And for each j < i, res[j] is correct by spec
                forall |j: usize|
                    j < i ==>
                    res[j] == choices[(indices[j] as usize)][j],
            decreases indices.len() - i,
        {
            // pick the row index for this column `i`
            let idx: usize = indices[i] as usize;
            // side‐conditions ensuring safe indexing
            assert(idx < choices.len());
            assert(i < indices.len());
            // every row has length == indices.len()
            assert(choices[idx].len() == indices.len());
            // so indexing at column i is safe
            assert(i < choices[idx].len());
            let val: f64 = choices[idx][i];
            res.push(val);
            i = i + 1;
        }
        res
    }
}

